import React, { useState, useEffect } from 'react';
import './modal.css';
import { useModal } from '../ContextAPI/ModalContext';
import axios from 'axios';
import toast from "react-hot-toast";


const CodeModal = ({ title, initialcode, language ,mode,codeid}) => {
   
    // console.log(title,initialcode,language,mode);

    const [Language, setLanguage] = useState(language);
    const [newCode, setNewCode] = useState(initialcode);
    const [Title,SetTitle]=useState(title);
    const { openModal, setOpenModal } = useModal();
    const id = localStorage.getItem("userId");



   
   

    const handleCloseModal = () => {
        setOpenModal(false);
    };


    const handleSave = async (e) => {
        e.preventDefault();
        // setLoading(true);
        try {
            const token=localStorage.getItem('token');
           
            if(!token){
            //    console.log('token empty')
            toast.error('Login to Continue');
            }
            const config = {
               headers: {
                   Authorization: `Bearer ${token}`
               }
           };
            const { data } = await axios.post("/api/v1/code/create-code", {
                title: Title,
                language: Language,
                description: newCode,
                user:id,
            },config);

            if (data?.success) {
                toast.success(`${data.message}`);
                handleCloseModal(); 
            }
            else {
                toast.error(`${data.message}`);
            }
        } catch (error) {
            console.error(error);
        }finally{
            
        }
    };

    const saveEditedCode = async () => {
        try {
            const token=localStorage.getItem('token');
           
            if(!token){
            //    console.log('token empty')
            toast.error('Login to Continue');
            }
            const config = {
               headers: {
                   Authorization: `Bearer ${token}`
               }
           };
          const { data } = await axios.put(`/api/v1/code/update-code/${codeid}`, {
            title: Title,
            language:Language,
            description: newCode,
          },config);
          toast.success(`${data.message}`);
          
         setOpenModal(false);
        } catch (error) {
          console.error(error);
        }
      };
    

    return (
        <div className={openModal ? 'modal-container open' : 'modal-container'}>
            <div className="modal-content">
                

                 <input className='modal-title' name='title' value={Title} onChange={(e)=>SetTitle(e.target.value)} />
                   
                   
                
                
                <select value={Language} onChange={(e) => setLanguage(e.target.value)}>
                    <option value={'cpp'}>C++</option>
                    <option value={'py'}>Python</option>
                    <option value={'c'}>C</option>
                </select>
                
                <textarea className='modal-code' name='code' value={newCode} onChange={(e) => setNewCode(e.target.value)}></textarea>
                
                <div className='modal-btns'>
                    {
                        mode==='edit'?  <button onClick={saveEditedCode} className='modal-btn' >Update</button>
                        : <button onClick={handleSave} className='modal-btn'>Save</button>
                    }
                   
                    <button onClick={handleCloseModal} className='modal-btn'>Close</button>
                </div>
            </div>
        </div>
    );
};

export default CodeModal;
